                # Recolor the matching copy outside the marker's cavity.
                for _, cells in copies:
                    for r,c in cells:
                        out[r][c] = marker_color
                return out

    # Some markers have a stepped outline rather than a simple L. Fill a small
    # contrasting component embedded in the concavity of the largest object.
    if objs:
        marker_color, marker = max(objs, key=lambda z: len(z[1]))
        r0,r1,c0,c1 = _rect(marker)
        for color,cells in objs:
            if color == marker_color or len(cells) < 2:
                continue
            if all(r0 <= r <= r1 and c0 <= c <= c1 for r,c in cells):
                # Require the component to be in a non-full part of the marker bbox.
                if any((r,c) not in marker for r,c in cells):
                    for r,c in cells:
                        out[r][c] = marker_color
                    return out
    return out
